CREATE OR REPLACE FUNCTION public.combat_effect_v2_gate(p_state jsonb, p_unit jsonb, p_tgt jsonb, p_att jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare clk int := (p_state->>'clock')::int;
begin
  return case p_att->>'k'
    when 'self_has' then combat_v2_status_on(p_unit, p_att->>'status', clk) is not null
